-- SHA-256 airports.csv: 85b63e21319fcd648d4741872205bbb1c89000d39bb1ded2cf41d8d11c7fe518 (local snapshot mtime 2026-11-20T14:46:33+00:00)
-- SHA-256 airlines.dat: 39be1a432e8b04ebc12860c29281c974a9cb52169c82b2456a835d66ab1548a1 (local snapshot mtime 2026-11-20T14:46:34+00:00)
-- SHA-256 routes.dat: bd373706238134f619c624c606dccc74c05c2582a977c489c81de501735f2390 (local snapshot mtime 2026-11-20T14:46:35+00:00)
DROP DATABASE IF EXISTS w03_aviation;
CREATE DATABASE w03_aviation CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE w03_aviation;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET @practice_saved_autocommit = @@autocommit;
SET autocommit = 0;

CREATE TABLE country (
    country_code CHAR(2) PRIMARY KEY,
    country_name VARCHAR(100) NOT NULL,
    continent CHAR(2)
);



CREATE TABLE airport (
    airport_id INT PRIMARY KEY,
    ident VARCHAR(12) NOT NULL,
    airport_type VARCHAR(25) NOT NULL,
    airport_name VARCHAR(200) NOT NULL,
    latitude DECIMAL(20,17),
    longitude DECIMAL(20,17),
    elevation_ft INT,
    country_code CHAR(2) NOT NULL,
    municipality VARCHAR(150),
    scheduled_service VARCHAR(3),
    icao_code VARCHAR(8),
    iata_code VARCHAR(8),
    FOREIGN KEY (country_code) REFERENCES country(country_code)
);


















CREATE TABLE airline (
    airline_id INT PRIMARY KEY,
    airline_name VARCHAR(150) NOT NULL,
    iata_code VARCHAR(8),
    icao_code VARCHAR(8),
    callsign VARCHAR(100),
    country_name VARCHAR(100),
    active CHAR(1) NOT NULL
);




CREATE TABLE route (
    route_id INT PRIMARY KEY,
    airline_id INT NOT NULL,
    source_airport_id INT NOT NULL,
    destination_airport_id INT NOT NULL,
    source_code VARCHAR(8),
    destination_code VARCHAR(8),
    codeshare CHAR(1),
    stops INT NOT NULL,
    equipment VARCHAR(100),
    FOREIGN KEY (airline_id) REFERENCES airline(airline_id),
    FOREIGN KEY (source_airport_id) REFERENCES airport(airport_id),
    FOREIGN KEY (destination_airport_id) REFERENCES airport(airport_id)
);



































































































































































































































































COMMIT;
SET autocommit = @practice_saved_autocommit;
SET FOREIGN_KEY_CHECKS = 1;
